using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpStdioServer.Tools;

[McpServerToolType]
public sealed class ApiFetchTool
{
    [McpServerTool("fetch_api_data"),
     Description("Fetches data from an external API endpoint and returns the JSON response.")]
    public static async Task<string> FetchApiDataAsync(
        IHttpClientFactory httpClientFactory,
        [Description("The relative path to request (e.g. \"users/42\").")] string path,
        CancellationToken cancellationToken = default)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");

        var response = await client.GetAsync(path, cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
        return JsonSerializer.Serialize(json, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpStdioServer.Prompts;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt("summarize"),
     Description("Generates a concise summary of the provided text.")]
    public static IList<Microsoft.Extensions.AI.ChatMessage> Summarize(
        [Description("The text content to summarize.")] string text,
        [Description("Target summary length: 'short', 'medium', or 'long'. Default is 'medium'.")]
        string length = "medium")
    {
        var systemInstructions = length.ToLowerInvariant() switch
        {
            "short"  => "Summarize the following text in 1-2 sentences.",
            "long"   => "Provide a detailed summary of the following text, preserving key details.",
            _        => "Summarize the following text in a concise paragraph.",
        };

        return
        [
            new(Microsoft.Extensions.AI.ChatRole.User,
                $"{systemInstructions}\n\n{text}")
        ];
    }
}

